NativeSignal grp0_set_sprite_draw_enabled(VM& vm, Thread& thread) {
    const uint32_t enabled = thread.stack.pop();
    const uint32_t sprite = thread.stack.pop();
    if ((sprite & 0xFF000000U) != 0x80000000U ||
        vm.display_objects().count(sprite) == 0) {
        std::ostringstream message;
        message << "Grp0:0x54 invalid sprite handle 0x" << std::hex
                << std::uppercase << sprite;
        throw std::runtime_error(message.str());
    }
    vm.set_sprite_draw_enabled(sprite, enabled);
    return NativeSignal::Continue;
}
